UPDATE t_user
SET password_hash = #{pass}
WHERE id = #{id} AND auth_epoch = #{authEpoch}
  AND CAST(password_hash AS BINARY) = CAST(#{expectedHash} AS BINARY)

UPDATE t_user
SET stamps = #{stamps}
WHERE id = #{id}

UPDATE t_user
SET stamps = stamps + #{quantity}
WHERE id = #{id}

mapper.select:
SELECT id, name, password_hash AS pass, stamps, role, auth_epoch
FROM t_user
WHERE id = #{id}
